solutions.naive:
class Solution:
    def findMaxLength(self, nums: list[int]) -> int:
        best = 0
        for l in range(len(nums)):
            for r in range(l, len(nums)):
                z = o = 0
                for i in range(l, r + 1):
                    if nums[i] == 0:
                        z += 1
                    else:
                        o += 1
                if z == o:
                    best = max(best, r - l + 1)
        return best

