solutions.optimal:
class Solution:
    def findMaxLength(self, nums: list[int]) -> int:
        first = {0: -1}
        bal = best = 0
        for i, x in enumerate(nums):
            bal += 1 if x == 1 else -1
            if bal in first:
                best = max(best, i - first[bal])
            else:
                first[bal] = i
        return best

